{
  "layers": {
    "intent": [
      "docs/intent.md"
    ],
    "design": [
      "docs/design"
    ],
    "impl": [
      "src",
      "tests"
    ]
  },
  "not_in_git": [
    "intent"
  ],
  "roles": {
    "zones": [
      {
        "name": "design",
        "layer": "design",
        "paths": [
          "docs/design"
        ]
      },
      {
        "name": "product",
        "layer": "impl",
        "paths": [
          "src"
        ]
      },
      {
        "name": "tests",
        "layer": "impl",
        "paths": [
          "tests"
        ]
      },
      {
        "name": "test-part",
        "layer": "impl",
        "paths": [
          "src/a.txt"
        ],
        "part": {
          "description": "The block from BEGIN TESTS through END TESTS, including both marker lines.",
          "recognition": {
            "kind": "markers",
            "begin": "BEGIN TESTS",
            "end": "END TESTS"
          }
        }
      }
    ],
    "members": [
      {
        "name": "builder",
        "read_zones": [
          "design",
          "product",
          "tests"
        ],
        "write_zones": [
          "product"
        ],
        "duty": "Build assigned product design.",
        "model": "PROJECT_MODEL"
      },
      {
        "name": "tester",
        "read_zones": [
          "design",
          "product",
          "tests"
        ],
        "write_zones": [
          "tests",
          "test-part"
        ],
        "duty": "Build assigned tests and perform assigned checks.",
        "model": "PROJECT_MODEL"
      }
    ],
    "guard": {
      "read_zones": true,
      "write_zones": true,
      "shell": "literal"
    }
  }
}

